#define NOMINMAX
#include "tokenizer_file.hpp"
#include <cstdio>
int main(){try{std::string digest;auto b=tao::text::load_tokenizer("build/formal_tokenizer.bbp",digest);if(b.merges.size()!=16123)throw std::runtime_error("vocab");std::ifstream in("build/bpe_training_messages.bin",std::ios::binary);char magic[4];in.read(magic,4);size_t row=0,checked=0,bytes=0,tokens=0;while(in.peek()!=EOF){uint32_t n=0;for(int j=0;j<4;++j){int x=in.get();if(x<0)throw std::runtime_error("truncated length");n|=uint32_t(x)<<(8*j);}if(n>65536)throw std::runtime_error("length");std::string s(n,char(0));in.read(s.data(),n);if(!in)throw std::runtime_error("truncated body");if(row++%719!=0)continue;auto ids=b.encode(s);if(b.decode(ids)!=s)throw std::runtime_error("roundtrip");for(auto id:ids)if(id>=256&&id<261)throw std::runtime_error("special");++checked;bytes+=s.size();tokens+=ids.size();}printf("PASS full_vocab=%zu sampled_messages=%zu bytes=%zu tokens=%zu SHA256=%s\n",b.merges.size()+261,checked,bytes,tokens,digest.c_str());return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
